// Local subset of the C runtime API needed by the transpiled ImGui source.
// These routines are authored for this repository and do not copy the minc.dev host.

// Dear ImGui's copied math helpers use these C-runtime routines. The local
// implementations keep them available in the compiler's WebAssembly subset.
private {
    f64 ext_libc_atan_series(f64 value) {
        f64 square = value * value;
        f64 term = value;
        f64 sum = value;
        for i32 n = 1; n <= 36; n++ {
            term = -term * square;
            sum = sum + term / cast(f64, 2 * n + 1);
        }
        return sum;
    }

    f64 ext_libc_atan_positive(f64 value) {
        f64 pi = 3.14159265358979323846;
        if value > 1.0 { return pi * 0.5 - ext_libc_atan_positive(1.0 / value); }
        if value > 0.5 {
            return pi * 0.25 + ext_libc_atan_series((value - 1.0) / (value + 1.0));
        }
        return ext_libc_atan_series(value);
    }

    f64 ext_libc_sin(f64 value) {
        f64 pi = 3.14159265358979323846;
        f64 tau = 6.28318530717958647692;
        while value > pi { value = value - tau; }
        while value < -pi { value = value + tau; }
        if value > pi * 0.5 { value = pi - value; }
        else if value < -pi * 0.5 { value = -pi - value; }
        f64 square = value * value;
        f64 term = value;
        f64 sum = value;
        for i32 n = 1; n <= 12; n++ {
            term = -term * square / cast(f64, (2 * n) * (2 * n + 1));
            sum = sum + term;
        }
        return sum;
    }

    f64 ext_libc_atan2(f64 y, f64 x) {
        f64 pi = 3.14159265358979323846;
        if x > 0.0 {
            if y < 0.0 { return -ext_libc_atan_positive(-y / x); }
            return ext_libc_atan_positive(y / x);
        }
        if x < 0.0 {
            if y < 0.0 { return -pi + ext_libc_atan_positive(y / x); }
            return pi - ext_libc_atan_positive(-y / x);
        }
        if y > 0.0 { return pi * 0.5; }
        if y < 0.0 { return -pi * 0.5; }
        return 0.0;
    }
}

f64 sin(f64 value) { return ext_libc_sin(value); }
f32 sin(f32 value) { return cast(f32, ext_libc_sin(cast(f64, value))); }
f64 cos(f64 value) { return ext_libc_sin(value + 1.57079632679489661923); }
f32 cos(f32 value) { return cast(f32, ext_libc_sin(cast(f64, value) + 1.57079632679489661923)); }
f64 atan2(f64 y, f64 x) { return ext_libc_atan2(y, x); }
f32 atan2(f32 y, f32 x) { return cast(f32, ext_libc_atan2(cast(f64, y), cast(f64, x))); }
f64 acos(f64 value) { return ext_libc_atan2(sqrt(1.0 - value * value), value); }
f32 acos(f32 value) { return cast(f32, ext_libc_atan2(sqrt(1.0 - cast(f64, value) * cast(f64, value)), cast(f64, value))); }

f64 atof(u8* text) {
    u64 index = 0;
    while text[index] == 32 || text[index] == 9 || text[index] == 10 || text[index] == 13 { index++; }
    bool negative = false;
    if text[index] == 45 { negative = true; index++; }
    else if text[index] == 43 { index++; }

    f64 value = 0.0;
    bool any_digit = false;
    while text[index] >= 48 && text[index] <= 57 {
        value = value * 10.0 + cast(f64, text[index] - 48);
        index++;
        any_digit = true;
    }
    if text[index] == 46 {
        index++;
        f64 place = 0.1;
        while text[index] >= 48 && text[index] <= 57 {
            value = value + cast(f64, text[index] - 48) * place;
            place = place * 0.1;
            index++;
            any_digit = true;
        }
    }
    if !any_digit { return 0.0; }

    i32 exponent = 0;
    if text[index] == 69 || text[index] == 101 {
        index++;
        bool exponent_negative = false;
        if text[index] == 45 { exponent_negative = true; index++; }
        else if text[index] == 43 { index++; }
        while text[index] >= 48 && text[index] <= 57 && exponent < 308 {
            exponent = exponent * 10 + cast(i32, text[index] - 48);
            if exponent > 308 { exponent = 308; }
            index++;
        }
        if exponent_negative { exponent = 0 - exponent; }
    }
    while exponent > 0 { value = value * 10.0; exponent--; }
    while exponent < 0 { value = value / 10.0; exponent++; }
    return negative ? -value : value;
}

u64 strlen(u8* text) {
    u64 length = 0;
    while text[length] != 0 { length++; }
    return length;
}

u8* strncpy(u8* destination, u8* source, u64 count) {
    u64 i = 0;
    while i < count && source[i] != 0 { destination[i] = source[i]; i++; }
    while i < count { destination[i] = 0; i++; }
    return destination;
}

u8* strstr(u8* text, u8* needle) {
    if needle[0] == 0 { return text; }
    for u64 start = 0; text[start] != 0; start++ {
        u64 offset = 0;
        while needle[offset] != 0 && text[start + offset] == needle[offset] { offset++; }
        if needle[offset] == 0 { return &text[start]; }
    }
    return null;
}

void* memmove(void* destination, void* source, u64 count) {
    u8* dst = cast(u8*, destination);
    u8* src = cast(u8*, source);
    if cast(u64, destination) < cast(u64, source) {
        for u64 i = 0; i < count; i++ { dst[i] = src[i]; }
    } else if cast(u64, destination) > cast(u64, source) {
        for u64 i = count; i > 0; i-- { dst[i - 1] = src[i - 1]; }
    }
    return destination;
}

f64 round(f64 value) {
    if value < 0.0 { return ceil(value - 0.5); }
    return floor(value + 0.5);
}

f32 fmod(f32 value, f32 divisor) {
    if divisor == 0.0f { return 0.0f; }
    return value - trunc(value / divisor) * divisor;
}

f64 ext_libc_add_f64(f64 left, f64 right) { return left + right; }

f64 exp(f64 value) {
    if value > 700.0 { return 1.0e300; }
    if value < -700.0 { return 0.0; }
    f64 ln2 = 0.69314718055994530942;
    i32 scale = cast(i32, value / ln2);
    f64 reduced = value - cast(f64, scale) * ln2;
    f64 sum = 1.0;
    f64 term = 1.0;
    for i32 n = 1; n <= 24; n++ {
        term = term * reduced / cast(f64, n);
        sum = ext_libc_add_f64(sum, term);
    }
    while scale > 0 { sum = sum * 2.0; scale--; }
    while scale < 0 { sum = sum / 2.0; scale++; }
    return sum;
}

f64 log(f64 value) {
    if value <= 0.0 { return -1.0e300; }
    f64 mantissa = value;
    i32 scale = 0;
    while mantissa >= 2.0 { mantissa = mantissa / 2.0; scale++; }
    while mantissa < 1.0 { mantissa = mantissa * 2.0; scale--; }
    f64 z = (mantissa - 1.0) / (mantissa + 1.0);
    f64 z_squared = z * z;
    f64 term = z;
    f64 sum = term;
    for i32 n = 3; n <= 39; n += 2 {
        term = term * z_squared;
        sum = ext_libc_add_f64(sum, term / cast(f64, n));
    }
    return ext_libc_add_f64(
        2.0 * sum,
        cast(f64, scale) * 0.69314718055994530942
    );
}

f64 pow(f64 base, f64 exponent) {
    if exponent >= -64.0 && exponent <= 64.0 {
        i64 integer_exponent = cast(i64, exponent);
        if cast(f64, integer_exponent) == exponent {
            bool reciprocal = integer_exponent < 0;
            if reciprocal { integer_exponent = 0 - integer_exponent; }
            f64 result = 1.0;
            f64 factor = base;
            while integer_exponent > 0 {
                if (integer_exponent & 1) != 0 { result = result * factor; }
                factor = factor * factor;
                integer_exponent = integer_exponent >> 1;
            }
            return reciprocal ? 1.0 / result : result;
        }
    }
    if base <= 0.0 { return 0.0; }
    return exp(exponent * log(base));
}

f32 exp(f32 value) { return cast(f32, exp(cast(f64, value))); }
f32 log(f32 value) { return cast(f32, log(cast(f64, value))); }
f32 pow(f32 base, f32 exponent) {
    return cast(f32, pow(cast(f64, base), cast(f64, exponent)));
}

i32 strcmp(u8* left, u8* right) {
    u64 i = 0;
    while left[i] == right[i] && left[i] != 0 { i++; }
    return cast(i32, left[i]) - cast(i32, right[i]);
}

i32 memcmp(void* left, void* right, u64 count) {
    u8* left_bytes = cast(u8*, left);
    u8* right_bytes = cast(u8*, right);
    for u64 i = 0; i < count; i++ {
        if left_bytes[i] != right_bytes[i] {
            return cast(i32, left_bytes[i]) - cast(i32, right_bytes[i]);
        }
    }
    return 0;
}

void* memchr(void* memory, i32 needle, u64 count) {
    u8* bytes = cast(u8*, memory);
    u8 value = cast(u8, needle);
    while count > 0 {
        if bytes[0] == value { return bytes; }
        bytes++;
        count--;
    }
    return null;
}

i32 strncmp(u8* left, u8* right, u64 count) {
    u64 i = 0;
    while i < count && left[i] == right[i] && left[i] != 0 { i++; }
    if i == count { return 0; }
    return cast(i32, left[i]) - cast(i32, right[i]);
}

u8* strchr(u8* text, i32 character) {
    u8 needle = cast(u8, character);
    u64 i = 0;
    while true {
        if text[i] == needle { return &text[i]; }
        if text[i] == 0 { return null; }
        i++;
    }
}

i32 vsnprintf(u8* buffer, u64 size, u8* format, &... args) {
    if size == 0 { return cast(i32, strlen(format)); }
    u64 i = 0;
    while i + 1 < size && format[i] != 0 {
        buffer[i] = format[i];
        i++;
    }
    buffer[i] = 0;
    return cast(i32, strlen(format));
}

// The ImGui demo does not load persisted settings. Returning no conversions
// keeps its optional .ini parsing inert without importing a host libc scanner.
i32 sscanf(u8* text, u8* format, ...) { return 0; }

void qsort(void* base, u64 count, u64 width, fn(void*, void*): i32 compare) {
    u8* bytes = cast(u8*, base);
    if count < 2 || width == 0 { return; }
    for u64 i = 0; i < count - 1; i++ {
        for u64 j = 0; j < count - i - 1; j++ {
            u8* left = &bytes[j * width];
            u8* right = &bytes[(j + 1) * width];
            if compare(left, right) > 0 {
                for u64 k = 0; k < width; k++ {
                    u8 tmp = left[k];
                    left[k] = right[k];
                    right[k] = tmp;
                }
            }
        }
    }
}

