// Shortest round-trip conversion is provided by the runtime's decimal formatter.
// The C++ backend uses the runtime formatter; the native backends compile this minc version (the
// free-format digit generation of Burger and Dybvig with exact big integers), selected by the define the
// native drivers set. Layout: positional notation for 1.0e-4 <= |x| < 1.0e21, else d.ddde<exponent>.
when defined(VerminNativeBackend) {
    // Big unsigned integers: little-endian 32-bit limbs; every operation takes the number of limbs in use.
    void mc_big_set(u32* a, u64 value) {
        // The array is zero on entry (a fresh local); set writes the two low limbs.
        a[0] = cast(u32, value & 4294967295);
        a[1] = cast(u32, value >> 32);
    }
    void mc_big_shl(u32* a, i32 bits, i32 n) {
        i32 words = bits / 32;
        i32 rest = bits % 32;
        if words > 0 {
            for i32 i = n - 1; i >= 0; i-- {
                if i >= words { a[i] = a[i - words]; } else { a[i] = 0; }
            }
        }
        if rest > 0 {
            for i32 i = n - 1; i >= 0; i-- {
                u32 lower = 0;
                if i > 0 { lower = a[i - 1] >> cast(u32, 32 - rest); }
                a[i] = (a[i] << cast(u32, rest)) | lower;
            }
        }
    }
    void mc_big_mul_small(u32* a, u32 factor, i32 n) {
        u64 carry = 0;
        for i32 i = 0; i < n; i++ {
            u64 product = cast(u64, a[i]) * cast(u64, factor) + carry;
            a[i] = cast(u32, product & 4294967295);
            carry = product >> 32;
        }
    }
    i32 mc_big_compare(u32* a, u32* b, i32 n) {
        for i32 i = n - 1; i >= 0; i-- {
            if a[i] > b[i] { return 1; }
            if a[i] < b[i] { return -1; }
        }
        return 0;
    }
    void mc_big_add(u32* a, u32* b, i32 n) {
        u64 carry = 0;
        for i32 i = 0; i < n; i++ {
            u64 sum = cast(u64, a[i]) + cast(u64, b[i]) + carry;
            a[i] = cast(u32, sum & 4294967295);
            carry = sum >> 32;
        }
    }
    void mc_big_sub(u32* a, u32* b, i32 n) {
        i64 borrow = 0;
        for i32 i = 0; i < n; i++ {
            i64 difference = cast(i64, a[i]) - cast(i64, b[i]) - borrow;
            if difference < 0 { difference = difference + 4294967296; borrow = 1; } else { borrow = 0; }
            a[i] = cast(u32, difference);
        }
    }
    // Shortest digits of mantissa * 2^exponent (mantissa has `precision` bits); writes at most 24 digits and
    // returns their count, with the decimal exponent of the first digit in *point (value = d.ddd * 10^point).
    i32 mc_float_digits(u64 mantissa, i32 exponent, i32 precision, i32 minimum_exponent, u8* digits, i32* point) {
        u32[80] r;
        u32[80] s;
        u32[80] up;
        u32[80] down;
        u32[80] t;
        bool even = (mantissa & 1) == 0;
        u64 hidden = 1;
        hidden = hidden << cast(u64, precision - 1);
        bool boundary = mantissa == hidden && exponent != minimum_exponent;
        // Estimate: one more than floor(log10 of the value), which is the decimal point or one above it.
        i32 bits = 0;
        u64 probe = mantissa;
        while probe != 0 { bits = bits + 1; probe = probe >> 1; }
        i64 binary_exponent = cast(i64, exponent + bits - 1);
        i64 estimate = ((binary_exponent * 1292913986) >> 32) + 1;
        i32 spread = exponent;
        if spread < 0 { spread = -spread; }
        i32 scale = cast(i32, estimate);
        if scale < 0 { scale = -scale; }
        // Limbs in use: s and r stay below 2^(spread + 4 * scale + precision + 8).
        i32 n = (64 + spread + scale * 4 + precision) / 32 + 2;
        if n > 80 { n = 80; }
        if exponent >= 0 {
            mc_big_set(&r[0], mantissa);
            mc_big_set(&up[0], 1);
            mc_big_set(&down[0], 1);
            mc_big_shl(&up[0], exponent, n);
            mc_big_shl(&down[0], exponent, n);
            if boundary {
                mc_big_shl(&r[0], exponent + 2, n);
                mc_big_set(&s[0], 4);
                mc_big_shl(&up[0], 1, n);
            } else {
                mc_big_shl(&r[0], exponent + 1, n);
                mc_big_set(&s[0], 2);
            }
        } else {
            mc_big_set(&r[0], mantissa);
            mc_big_set(&s[0], 1);
            if boundary {
                mc_big_shl(&r[0], 2, n);
                mc_big_shl(&s[0], 2 - exponent, n);
                mc_big_set(&up[0], 2);
                mc_big_set(&down[0], 1);
            } else {
                mc_big_shl(&r[0], 1, n);
                mc_big_shl(&s[0], 1 - exponent, n);
                mc_big_set(&up[0], 1);
                mc_big_set(&down[0], 1);
            }
