// zlib framing and checksums supplied by the native runtime.
// The C++ backend uses runtime/compression.hpp (system zlib); the native backends compile this minc
// version, selected by the define the native drivers set (see src/native/mod.rs).
import inflate;
import deflate;
when defined(VerminNativeBackend) {
    u32 crc32(u8* source, i32 length) {
        u32 crc = 4294967295;
        for i32 i = 0; i < length; i++ {
            crc = crc ^ cast(u32, source[i]);
            for i32 bit = 0; bit < 8; bit++ {
                if (crc & 1) != 0 { crc = (crc >> 1) ^ 3988292384; } else { crc = crc >> 1; }
            }
        }
        return crc ^ 4294967295;
    }
    u32 adler32(u8* source, i32 length) {
        u32 a = 1;
        u32 b = 0;
        for i32 i = 0; i < length; i++ {
            a = (a + cast(u32, source[i])) % 65521;
            b = (b + a) % 65521;
        }
        return (b << 16) | a;
    }
    i32 zlib_compress(u8* source, i32 length, u8* destination, i32 capacity, i32* written) {
        if capacity < 6 { return -1; }
        i32 n = 0;
        i32 status = deflate(source, length, destination + 2, capacity - 6, &n);
        if status != 0 { return status; }
        destination[0] = 120;
        destination[1] = 1;
        u32 checksum = adler32(source, length);
        for i32 i = 0; i < 4; i++ { destination[n + 2 + i] = cast(u8, checksum >> cast(u32, 24 - i * 8)); }
        if written != null { *written = n + 6; }
        return 0;
    }
    // Inflate the deflate data at `start`. The decoder sees the input without the last `trailer` bytes (so a
    // short trailer shows up as a truncated stream, as in the reference); the caller checks the trailer.
    i32 mc_zlib_body(mc_inflate_state* s, u8* source, i32 length, i32 trailer, u8* destination, i32 capacity, i32 start) {
        s.source = source;
        s.length = length - trailer;
        s.position = start;
        s.dest = destination;
        s.capacity = capacity;
        if mc_inflate_stream(s) != 0 { return s.error; }
        return 0;
    }
    i32 zlib_decompress(u8* source, i32 length, u8* destination, i32 capacity, i32* written) {
        if length < 0 || capacity < 0 { return -1; }
        if length < 7 { return -1; }
        i32 cmf = cast(i32, source[0]);
        i32 flg = cast(i32, source[1]);
        if (cmf & 15) != 8 { return -8; }
        if ((cmf << 8) + flg) % 31 != 0 { return -2; }
        if (flg & 32) != 0 { return -3; }
        mc_inflate_state s = {};
        i32 status = mc_zlib_body(&s, source, length, 4, destination, capacity, 2);
        if status != 0 { return status; }
        if s.position + 4 > length { return -1; }
        u32 expected = (cast(u32, source[s.position]) << 24) | (cast(u32, source[s.position + 1]) << 16) | (cast(u32, source[s.position + 2]) << 8) | cast(u32, source[s.position + 3]);
        if expected != adler32(destination, s.produced) { return -4; }
        if written != null { *written = s.produced; }
        return 0;
    }
