        if length < 19 { return -1; }
        if source[0] != 31 || source[1] != 139 || source[2] != 8 { return -8; }
        // Reserved and text flag bits are ignored, and the header checksum is skipped, not verified.
        i32 flags = cast(i32, source[3]);
        i32 position = 10;
        if (flags & 4) != 0 {
            if position + 2 > length { return -1; }
            i32 extra = cast(i32, source[position]) | (cast(i32, source[position + 1]) << 8);
            position = position + 2 + extra;
            if position > length { return -1; }
        }
        if (flags & 8) != 0 {
            while position < length && source[position] != 0 { position = position + 1; }
            if position >= length { return -1; }
            position = position + 1;
        }
        if (flags & 16) != 0 {
            while position < length && source[position] != 0 { position = position + 1; }
            if position >= length { return -1; }
            position = position + 1;
        }
        if (flags & 2) != 0 {
            if position + 2 > length { return -1; }
            position = position + 2;
        }
        mc_inflate_state s = {};
        i32 status = mc_zlib_body(&s, source, length, 8, destination, capacity, position);
        if status != 0 { return status; }
        if s.position + 8 > length { return -1; }
        u32 crc = cast(u32, source[s.position]) | (cast(u32, source[s.position + 1]) << 8) | (cast(u32, source[s.position + 2]) << 16) | (cast(u32, source[s.position + 3]) << 24);
