@define "VERMINC_IMGUI_EXT_LIBC"

import "sokol_all.mc";
import "imgui.mc";
// sokol_imgui.h shader as minc @shader functions, replacing the
// upstream header's per-backend source text and bytecode blobs.
//
// Interface mirrors the upstream sokol-shdc program:
//   attrs: position(0) f2, texcoord0(1) f2, color0(2) f4
//   uniform block 0 (vertex): disp_size + gamma, matching
//   _simgui_vs_params_t
//   fragment: texture(0) + sampler(0); a second fragment variant
//   declares the pair unfilterable/nonfiltering for textures that
//   cannot be filtered (R32F etc.), mirroring the upstream
//   def_shd / shd_unfilterable split.

// Explicit WebGL2 shaders keep the ImGui renderer independent of generated
// ShaderMeta helper types while matching sokol_imgui.h's vertex layout.
sg_shader _simgui_minc_make_shader(bool unfilterable) {
    sg_shader_desc desc;
    desc.vertex_func.source = "#version 300 es\nprecision highp float;\nin vec2 position;\nin vec2 texcoord0;\nin vec4 color0;\nuniform vec2 disp_size;\nuniform float gamma;\nout vec2 uv;\nout vec4 color;\nvoid main() { gl_Position = vec4((position.x / disp_size.x - 0.5) * 2.0, (position.y / disp_size.y - 0.5) * -2.0, 0.5, 1.0); uv = texcoord0; color = vec4(pow(abs(color0.rgb), vec3(gamma)), color0.a); }\n";
    desc.fragment_func.source = "#version 300 es\nprecision highp float;\nin vec2 uv;\nin vec4 color;\nuniform sampler2D tex;\nout vec4 frag_color;\nvoid main() { frag_color = texture(tex, uv) * color; }\n";
    desc.attrs[0].glsl_name = "position";
    desc.attrs[1].glsl_name = "texcoord0";
    desc.attrs[2].glsl_name = "color0";
    desc.uniform_blocks[0].stage = SG_SHADERSTAGE_VERTEX;
    desc.uniform_blocks[0].size = 16;
    desc.uniform_blocks[0].glsl_uniforms[0].type = SG_UNIFORMTYPE_FLOAT2;
    desc.uniform_blocks[0].glsl_uniforms[0].array_count = 1;
    desc.uniform_blocks[0].glsl_uniforms[0].glsl_name = "disp_size";
    desc.uniform_blocks[0].glsl_uniforms[1].type = SG_UNIFORMTYPE_FLOAT;
    desc.uniform_blocks[0].glsl_uniforms[1].array_count = 1;
    desc.uniform_blocks[0].glsl_uniforms[1].glsl_name = "gamma";
    desc.uniform_blocks[0].glsl_uniforms[2].type = SG_UNIFORMTYPE_FLOAT;
    desc.uniform_blocks[0].glsl_uniforms[2].array_count = 1;
    desc.uniform_blocks[0].glsl_uniforms[2].glsl_name = "_sokol_ub_pad";
    desc.views[0].texture.stage = SG_SHADERSTAGE_FRAGMENT;
    desc.views[0].texture.image_type = SG_IMAGETYPE_2D;
    desc.views[0].texture.sample_type = unfilterable ? SG_IMAGESAMPLETYPE_UNFILTERABLE_FLOAT : SG_IMAGESAMPLETYPE_FLOAT;
    desc.samplers[0].stage = SG_SHADERSTAGE_FRAGMENT;
    desc.samplers[0].sampler_type = unfilterable ? SG_SAMPLERTYPE_NONFILTERING : SG_SAMPLERTYPE_FILTERING;
    desc.texture_sampler_pairs[0].stage = SG_SHADERSTAGE_FRAGMENT;
    desc.texture_sampler_pairs[0].view_slot = 0;
    desc.texture_sampler_pairs[0].sampler_slot = 0;
    desc.texture_sampler_pairs[0].glsl_name = "tex";
    desc.label = unfilterable ? "sokol-imgui-unfilterable-shader" : "sokol-imgui-shader";
    return sg_make_shader(&desc);
}

sg_shader _simgui_minc_shader() {
    return _simgui_minc_make_shader(false);
}

sg_shader _simgui_minc_shader_unfilterable() {
    return _simgui_minc_make_shader(true);
}

// OS answer for ImGuiConfigFlags MacOSXBehaviors (Cmd vs Ctrl
// shortcuts). The web build reports false, same as the shipped
// emscripten stub.
bool _simgui_minc_is_osx() {
    when os(macos) || os(ios) {
        return true;
    }
    when !(os(macos) || os(ios)) {
        return false;
    }
}

when !os(wasm) {
/*
    simgui_log_item

    An enum with a unique item for each log message, warning, error
    and validation layer message.
*/
enum simgui_log_item_t {
    SIMGUI_LOGITEM_OK = 0,
    SIMGUI_LOGITEM_BUFFER_OVERFLOW = 1,
    SIMGUI_LOGITEM_NEW_FRAME_NOT_CALLED_BEFORE_FLUSH = 2,
    SIMGUI_LOGITEM_FLUSH_CALLED_IN_SOKOLGFX_PASS = 3,
    SIMGUI_LOGITEM_FLUSH_NOT_CALLED_BEFORE_DRAW = 4,
    SIMGUI_LOGITEM_DRAW_CALLED_OUTSIDE_SOKOLGFX_RENDER_PASS = 5,
}

/*
    simgui_logger

    Used in simgui_desc_t to provide a logging function. Please be aware
    that without logging function, sokol-imgui will be completely
    silent, e.g. it will not report errors, warnings and
    validation layer messages. For maximum error verbosity,
    compile in debug mode (e.g. NDEBUG *not* defined) and install
    a logger (for instance the standard logging function from sokol_log.h).
*/
struct simgui_logger_t {
    fn(u8*, u32, u32, u8*, u32, u8*, void*): void func;
    void* user_data;
}

