bool ast_parser_starts(str s,u8 c){return s.len>0&&s.data[0]==c;}
str ast_parser_filename(str file){
    // std::path::Path::file_name ignores trailing separators and terminal '.'.
    i32 end=file.len;while end>0&&file.data[end-1]=='/'{end--;}
    while end>0{ i32 start=end;while start>0&&file.data[start-1]!='/'{start--;}
        str part=sc_sub(file,start,end);if sc_equal(part,"."){end=start;while end>0&&file.data[end-1]=='/'{end--;}continue;}
        if sc_equal(part,".."){return "";}return part;
    }return "";
}
