void ast_parser_debug_hex(ScBuffer* out,i32 point){if point>=16{ast_parser_debug_hex(out,point/16);}str hex="0123456789abcdef";sc_byte(out,hex.data[point%16]);}
str ast_parser_debug_string(str text){
    ScBuffer out;sc_byte(&out,'"');
    for i32 i=0;i<text.len;i++{u8 c=text.data[i];
        if c=='"'||c=='\\'{sc_byte(&out,'\\');sc_byte(&out,c);}
        else if c==0{sc_add(&out,"\\0");}else if c==9{sc_add(&out,"\\t");}else if c==10{sc_add(&out,"\\n");}else if c==13{sc_add(&out,"\\r");}
        else if c<32||c==127{sc_add(&out,"\\u{");ast_parser_debug_hex(&out,cast(i32,c));sc_byte(&out,'}');}
        else if c>=128{
            i32 start=i;i32 point=cast(i32,c);i32 count=0;
            if c<224{point=point&31;count=1;}else if c<240{point=point&15;count=2;}else{point=point&7;count=3;}
