    }sc_byte(&out,'"');return sc_text(&out);
}
AstParser ast_parser_new(str s,str file){AstParser p;AstLexResult r=ast_lex(s);p.tokens=r.tokens;p.error=r.error;p.file=file;p.marks=ast_line_marks;return p;}
AstCheckpoint ast_parser_checkpoint(AstParser* p){return AstCheckpoint{p.pos,p.splits_len};}
void ast_parser_restore(AstParser* p,AstCheckpoint cp){while p.splits_len>cp.splits{p.splits_len--;p.tokens.data[p.splits[p.splits_len]].text=">>";}p.pos=cp.pos;p.error="";}
str ast_parser_at(AstParser* p){if p.pos>=p.tokens.len{return "<eof>";}return p.tokens.data[p.pos].text;}
str ast_parser_next(AstParser* p){if p.pos+1>=p.tokens.len{return "<eof>";}return p.tokens.data[p.pos+1].text;}
bool ast_parser_eat(AstParser* p,str s){if p.error.len>0{return false;}if sc_equal(ast_parser_at(p),s){p.pos++;return true;}return false;}
str ast_parser_take(AstParser* p){str s=ast_parser_at(p);if !sc_equal(s,"<eof>"){p.pos++;}return s;}
void ast_parser_err(AstParser* p,str s){if p.error.len>0{return;}AstToken t=p.tokens.data[p.pos];p.error=format("{}:{}:{}: {}; found '{}'",p.file,t.line,t.col,s,t.text);}
bool ast_parser_need(AstParser* p,str s){if ast_parser_eat(p,s){return true;}ast_parser_err(p,format("expected '{}'",s));return false;}
str ast_parser_name(AstParser* p){if p.error.len>0{return "";}if ast_ident(ast_parser_at(p)){return ast_parser_take(p);}ast_parser_err(p,"expected identifier");return "";}
bool ast_parser_gt(AstParser* p){if p.error.len>0{return false;}if sc_equal(ast_parser_at(p),">>"){p.splits=sc_table_reserve<i32>(p.splits,&p.splits_cap,p.splits_len+1);p.splits[p.splits_len]=p.pos;p.splits_len++;p.tokens.data[p.pos].text=">";return true;}return ast_parser_need(p,">");}
