struct ScBuffer { u8* data; i32 len, cap; }
struct ScToken { str text; i32 kind; i32 line; i32 col; }
struct ScTokens { ScToken* data; i32 len, pos; }

void sc_fail(str message) {
    eprint("selfhost: {}\n", message);
    exit(1);
}

// Geometric growth preserves table indices; callers do not retain element pointers.
T* sc_table_reserve<T>(T* data,i32* capacity,i32 needed){
    if needed<0{sc_fail("table too large");}
    if needed<=*capacity{return data;}
    i32 size=*capacity;if size<16{size=16;}
    while size<needed{if size>536870911{sc_fail("table too large");}size*=2;}
    T* grown=cast(T*,realloc(data,cast(i64,size)*sizeof(T)));
    if grown==null{sc_fail("out of memory");}*capacity=size;return grown;
}

void sc_reserve(ScBuffer* buffer, i32 extra) {
    if extra < 0 || buffer.len > 1073741823 - extra { sc_fail("buffer too large"); }
    i32 needed = buffer.len + extra;
    if needed <= buffer.cap { return; }
    i32 capacity = buffer.cap;
    if capacity < 64 { capacity = 64; }
    while capacity < needed { capacity *= 2; }
    u8* data = cast(u8*, realloc(buffer.data, capacity));
    if data == null { sc_fail("out of memory"); }
    if sc_profile_active{sc_profile_buffer_growths++;sc_profile_buffer_capacity_bytes+=cast(u64,capacity);}
    buffer.data = data;
    buffer.cap = capacity;
}

void sc_byte(ScBuffer* buffer, u8 value) {
    sc_reserve(buffer, 1);
    buffer.data[buffer.len] = value;
    buffer.len++;
}

void sc_add(ScBuffer* buffer, str text) {
    sc_reserve(buffer, text.len);
    // One block copy unless the source still lives inside this buffer's used
    // range (then the byte-by-byte loop preserves the old forward-copy order).
    i64 distance=cast(i64,text.data-cast(u8*,buffer.data));
    if text.len>0&&distance>0-cast(i64,text.len)&&distance<cast(i64,buffer.len+text.len){
        if sc_profile_active{sc_profile_sc_add_byte_loops+=cast(u64,text.len);}
        for i32 index = 0; index < text.len; index++ {
            buffer.data[buffer.len + index] = text.data[index];
        }
    }else if text.len>0{
        memcpy(&buffer.data[buffer.len],text.data,cast(i64,text.len));
    }
    buffer.len += text.len;
}

str sc_text(ScBuffer* buffer) { return str{buffer.data, buffer.len}; }

str sc_cat(str left, str right) {
    ScBuffer buffer;
    sc_add(&buffer, left);
    sc_add(&buffer, right);
    return sc_text(&buffer);
}

bool sc_equal(str left, str right) {
    if left.len != right.len { return false; }
    for i32 index = 0; index < left.len; index++ {
        if left.data[index] != right.data[index] { return false; }
    }
    return true;
}

str sc_sub(str text, i32 start, i32 end) {
    if start < 0 || end < start || end > text.len { sc_fail("invalid substring"); }
    return str{text.data + start, end - start};
}

u8* sc_cstr(str text) {
    if text.len > 1073741822 { sc_fail("string too large"); }
    u8* result = alloc<u8>(text.len + 1);
    if result == null { sc_fail("out of memory"); }
    for i32 index = 0; index < text.len; index++ { result[index] = text.data[index]; }
    result[text.len] = 0;
    return result;
}

str sc_read(str path) {
    u8* name = sc_cstr(path);
    i64 handle = open(name, 0);
    free(name);
    if handle < 0 { sc_fail(sc_cat("cannot read ", path)); }
    ScBuffer buffer;
    while true {
        sc_reserve(&buffer, 4096);
        i32 count = read(handle, buffer.data + buffer.len, 4096);
        if count < 0 { close(handle); sc_fail(sc_cat("read failed: ", path)); }
        if count == 0 { break; }
        buffer.len += count;
    }
    close(handle);
    return sc_text(&buffer);
}

void sc_write(str path, str content) {
    u8* name = sc_cstr(path);
    i64 handle = open(name, 1);
    free(name);
    if handle < 0 { sc_fail(sc_cat("cannot write ", path)); }
    i32 done = 0;
    while done < content.len {
        i32 count = write(handle, content.data + done, content.len - done);
        if count <= 0 { close(handle); sc_fail(sc_cat("write failed: ", path)); }
        done += count;
    }
    close(handle);
}

str sc_quote(str text) {
    ScBuffer buffer;
    sc_byte(&buffer, '"');
    for i32 index = 0; index < text.len; index++ {
        u8 value = text.data[index];
        if value == '"' || value == '\\' {
            sc_byte(&buffer, '\\');
            sc_byte(&buffer, value);
        } else if value < 32 || value >= 127 {
            sc_byte(&buffer, '\\');
            sc_byte(&buffer, cast(u8, 48 + (value >> 6)));
            sc_byte(&buffer, cast(u8, 48 + ((value >> 3) & 7)));
            sc_byte(&buffer, cast(u8, 48 + (value & 7)));
        } else { sc_byte(&buffer, value); }
    }
    sc_byte(&buffer, '"');
    return sc_text(&buffer);
}

i32 sc_hex(u8 value) {
    if value >= '0' && value <= '9' { return cast(i32, value) - 48; }
    if value >= 'a' && value <= 'f' { return cast(i32, value) - 87; }
    if value >= 'A' && value <= 'F' { return cast(i32, value) - 55; }
    sc_fail("invalid hex escape"); return 0;
}

void sc_unicode(ScBuffer* output, i32 point) {
    if point < 0 || point > 1114111 || (point >= 55296 && point <= 57343) { sc_fail("invalid Unicode scalar"); }
    if point < 128 { sc_byte(output, cast(u8, point)); }
    else if point < 2048 {
        sc_byte(output, cast(u8, 192 | (point >> 6)));
        sc_byte(output, cast(u8, 128 | (point & 63)));
    } else if point < 65536 {
        sc_byte(output, cast(u8, 224 | (point >> 12)));
        sc_byte(output, cast(u8, 128 | ((point >> 6) & 63)));
        sc_byte(output, cast(u8, 128 | (point & 63)));
    } else {
        sc_byte(output, cast(u8, 240 | (point >> 18)));
        sc_byte(output, cast(u8, 128 | ((point >> 12) & 63)));
        sc_byte(output, cast(u8, 128 | ((point >> 6) & 63)));
        sc_byte(output, cast(u8, 128 | (point & 63)));
    }
}

str sc_literal(str text, bool character) {
    ScBuffer output;
    i32 index = 1; i32 end = text.len - 1;
    while index < end {
        u8 value = text.data[index]; index++;
        if value == '\\' {
            if index >= end { sc_fail("incomplete escape"); }
            u8 escape = text.data[index]; index++;
            if escape == 'n' { value = 10; }
            else if escape == 'r' { value = 13; }
            else if escape == 't' { value = 9; }
            else if escape == '0' { value = 0; }
            else if escape == '\\' || escape == '\'' || escape == '"' { value = escape; }
            else if escape == 'x' {
                if index + 2 > end { sc_fail("hex escape requires two digits"); }
                i32 point = sc_hex(text.data[index]) * 16 + sc_hex(text.data[index + 1]); index += 2;
                if character { sc_unicode(&output, point); continue; }
                value = cast(u8, point);
            } else if escape == 'u' {
                if index >= end || text.data[index] != '{' { sc_fail("invalid Unicode escape"); }
                index++; i32 point = 0; i32 digits = 0;
                while index < end && text.data[index] != '}' {
                    if digits >= 6 { sc_fail("Unicode escape requires one to six digits"); }
                    point = point * 16 + sc_hex(text.data[index]); index++; digits++;
                }
                if digits == 0 || index >= end { sc_fail("unterminated or empty Unicode escape"); }
                index++; sc_unicode(&output, point); continue;
            } else { sc_fail("unknown literal escape"); }
        }
        sc_byte(&output, value);
    }
    return sc_text(&output);
}

i32 sc_character(str text) {
    if text.len == 0 { sc_fail("empty character literal"); }
    i32 first = cast(i32, text.data[0]); i32 count = 1; i32 point = first; i32 minimum = 0;
    if first >= 194 && first <= 223 { count = 2; point = first & 31; minimum = 128; }
    else if first >= 224 && first <= 239 { count = 3; point = first & 15; minimum = 2048; }
    else if first >= 240 && first <= 244 { count = 4; point = first & 7; minimum = 65536; }
    else if first >= 128 { sc_fail("invalid UTF-8 character"); }
    if text.len != count { sc_fail("character literal must contain one scalar"); }
    for i32 index = 1; index < count; index++ {
        i32 next = cast(i32, text.data[index]);
        if next < 128 || next > 191 { sc_fail("invalid UTF-8 continuation"); }
        point = point * 64 + (next & 63);
    }
    if point < minimum || point > 1114111 || (point >= 55296 && point <= 57343) { sc_fail("invalid Unicode scalar"); }
    return point;
}

str sc_parent(str path) {
    i32 index = path.len - 1;
    while index >= 0 {
        if path.data[index] == '/' {
            if index == 0 { return sc_sub(path, 0, 1); }
            return sc_sub(path, 0, index);
        }
        index--;
    }
    return ".";
}

str sc_basename(str path) {
    i32 index = path.len - 1;
    while index >= 0 {
        if path.data[index] == '/' || path.data[index] == '\\' {
            return sc_sub(path, index + 1, path.len);
        }
        index--;
    }
    return path;
}

bool sc_alpha(u8 value) {
    return (value >= 'a' && value <= 'z') || (value >= 'A' && value <= 'Z') || value == '_';
}

bool sc_digit(u8 value) { return value >= '0' && value <= '9'; }

bool sc_operator(str text) {
    return sc_equal(text, "<<=") || sc_equal(text, ">>=") || sc_equal(text, "...") ||
        sc_equal(text, "==") || sc_equal(text, "!=") || sc_equal(text, "<=") || sc_equal(text, ">=") ||
        sc_equal(text, "&&") || sc_equal(text, "||") || sc_equal(text, "++") || sc_equal(text, "--") ||
        sc_equal(text, "+=") || sc_equal(text, "-=") || sc_equal(text, "*=") || sc_equal(text, "/=") ||
        sc_equal(text, "%=") || sc_equal(text, "&=") || sc_equal(text, "|=") || sc_equal(text, "^=") ||
        sc_equal(text, "<<") || sc_equal(text, ">>") || sc_equal(text, "..") || sc_equal(text, "->");
}

ScTokens sc_lex(str source) {
    ScTokens tokens;
    i32 capacity = 64;
    tokens.data = alloc<ScToken>(capacity);
    if tokens.data == null { sc_fail("out of memory"); }
    i32 index = 0;
    i32 line = 1;
    i32 col = 1;
    while index < source.len {
        i32 consumed_start = index;
        u8 value = source.data[index];
        if value == ' ' || value == '\t' || value == '\n' || value == '\r' { index++; }
        else if index + 1 < source.len && value == '/' && source.data[index + 1] == '/' {
            index += 2;
            while index < source.len && source.data[index] != '\n' { index++; }
        } else if index + 1 < source.len && value == '/' && source.data[index + 1] == '*' {
            index += 2;
            while index + 1 < source.len && !(source.data[index] == '*' && source.data[index + 1] == '/') { index++; }
            if index + 1 >= source.len { sc_fail("unterminated comment"); }
            index += 2;
        } else {
            i32 start = index;
            i32 kind = 5;
            if sc_alpha(value) {
                kind = 1;
                index++;
                while index < source.len && (sc_alpha(source.data[index]) || sc_digit(source.data[index])) { index++; }
            } else if sc_digit(value) || (value == '.' && index + 1 < source.len && sc_digit(source.data[index + 1])) {
                kind = 2;
                bool radix = false;
                if index + 1 < source.len && value == '0' {
                    u8 next = source.data[index + 1];
                    radix = next == 'x' || next == 'X' || next == 'b' || next == 'B';
                }
                index++;
                while index < source.len {
                    u8 next = source.data[index];
                    if sc_alpha(next) || sc_digit(next) { index++; }
                    else if next == '.' && !(index + 1 < source.len && source.data[index + 1] == '.') { index++; }
                    else if !radix && (next == '+' || next == '-') && (source.data[index - 1] == 'e' || source.data[index - 1] == 'E') { index++; }
                    else { break; }
                }
            } else if value == '"' || value == '\'' {
                kind = 3;
                if value == '\'' { kind = 4; }
                index++;
                while index < source.len && source.data[index] != value {
                    if source.data[index] == '\n' || source.data[index] == '\r' { sc_fail("unterminated literal"); }
                    if source.data[index] == '\\' {
                        index++;
                        if index >= source.len { sc_fail("unterminated escape"); }
                    }
                    index++;
                }
                if index >= source.len { sc_fail("unterminated literal"); }
                index++;
            } else {
                i32 width = 1;
                if index + 3 <= source.len && sc_operator(sc_sub(source, index, index + 3)) { width = 3; }
                else if index + 2 <= source.len && sc_operator(sc_sub(source, index, index + 2)) { width = 2; }
                index += width;
            }
            if tokens.len + 1 >= capacity {
                if capacity > 16777216 { sc_fail("too many tokens"); }
                capacity *= 2;
                tokens.data = cast(ScToken*, realloc(tokens.data, cast(i64, capacity) * sizeof(ScToken)));
                if tokens.data == null { sc_fail("out of memory"); }
            }
            tokens.data[tokens.len] = ScToken{sc_sub(source, start, index), kind, line, col};
            tokens.len++;
        }
        for i32 position = consumed_start; position < index; position++ {
            if source.data[position] == '\n' { line++; col=1; } else { col++; }
        }
    }
    tokens.data[tokens.len] = ScToken{"", 0, line, col};
    tokens.len++;
    return tokens;
}

// Open-addressed lookup only: source-order arrays remain the emission authority.
struct ScIndexEntry {str key;i32 scope;i32 value;}
struct ScIndex {ScIndexEntry* entries;i32 capacity;i32 count;}
u32 sc_index_hash(str key,i32 scope){
    u32 hash=2166136261;
    for i32 i=0;i<key.len;i++{hash=(hash^cast(u32,key.data[i]))*16777619;}
    if sc_profile_active{sc_profile_index_hash_bytes+=cast(u64,key.len);}
    return (hash^cast(u32,scope))*16777619;
}
i32 sc_index_slot(ScIndex* index,str key,i32 scope){
    i32 slot=cast(i32,sc_index_hash(key,scope)&cast(u32,index.capacity-1));
    while index.entries[slot].value!=0{
        if sc_profile_active{sc_profile_index_probes++;}
        if index.entries[slot].scope==scope{if sc_profile_active{sc_profile_index_key_comparisons++;}if sc_equal(index.entries[slot].key,key){break;}}
        slot=(slot+1)&(index.capacity-1);
    }
    return slot;
}
i32 sc_index_get(ScIndex* index,str key,i32 scope){
    if sc_profile_active{sc_profile_index_gets++;}
    if index.capacity==0{return -1;}
    return index.entries[sc_index_slot(index,key,scope)].value-1;
}
i32 sc_index_slot_hash(ScIndex* index,u32 hash,i32 scope,str key){
    i32 slot=cast(i32,hash&cast(u32,index.capacity-1));
    while index.entries[slot].value!=0{
        if sc_profile_active{sc_profile_index_probes++;}
        if index.entries[slot].scope==scope{if sc_profile_active{sc_profile_index_key_comparisons++;}if sc_equal(index.entries[slot].key,key){break;}}
        slot=(slot+1)&(index.capacity-1);
    }
    return slot;
}
i32 sc_index_get_hash(ScIndex* index,u32 hash,str key,i32 scope){
    if sc_profile_active{sc_profile_index_gets++;}
    if index.capacity==0{return -1;}
    return index.entries[sc_index_slot_hash(index,hash,scope,key)].value-1;
}
u32 sc_index_hash_of(str key,i32 scope){return sc_index_hash(key,scope);}
void sc_index_put(ScIndex* index,str key,i32 scope,i32 value){
    if sc_profile_active{sc_profile_index_puts++;}
    if index.capacity==0||index.count>=index.capacity/2{
        i32 capacity=index.capacity;
        if capacity>536870911{sc_fail("index too large");}
        i32 size=capacity==0?16:capacity*2;
        ScIndexEntry* old=index.entries;
        index.entries=alloc<ScIndexEntry>(size);if index.entries==null{sc_fail("out of memory");}
        index.capacity=size;
        for i32 i=0;i<size;i++{index.entries[i].value=0;}
        for i32 i=0;i<capacity;i++{if old[i].value!=0{index.entries[sc_index_slot(index,old[i].key,old[i].scope)]=old[i];}}
        free(old);
    }
    i32 slot=sc_index_slot(index,key,scope);
    if index.entries[slot].value==0{index.count++;}
    index.entries[slot]=ScIndexEntry{key,scope,value+1};
}
void sc_index_clear(ScIndex* index){free(index.entries);index.entries=null;index.capacity=0;index.count=0;}

